C=[]
species=skill('动植人的生理与感应通讯','细胞保留叶绿素等植物特性，可进行特殊呼吸循环，以脑波在约一百公里范围内同类传讯；可借细胞培养产生独立后代。','受刺激时脸色可泛暗绿；幼生阶段在培育环境中呈植物般外观。',['同类联络','适应寒冷与不同呼吸条件','在合适环境培育下一代'],'后代是独立的人，不是随意操纵的分身；仍会被暴力伤害，缺乏战斗反应；通讯距离不是攻击范围。')
body={'durability':'比普通人体更适应自然寒冷，仍能被石块、利器和事故伤害；不把植物特性当无限再生。','energy':'同类脑波通讯有实证，不能自动变成精神杀伤。','stamina':'有植物相关代谢与特殊生理，仍需具体环境和生活支持。'}
entries=[
('dabao_plant','达宝（飞行工程师）',
'达宝在航空公司担任飞行工程师，从学生时代就拒绝向石灰水吹气，因怕暴露不同的呼吸机制而被叫作倔强。他照料温室中的后代，对卫斯理随手折取幼体的态度愤怒，并坚持植物与动物的生命都不应因外貌而被轻视。他与生物专家单相讨论另一条进化道路，既想被理解又不能直接泄露身份。飞机事故后他参与掩饰、转移马基并一度麻醉调查者，后来主动邀请卫白来到聚居地，驾船接送，成为沟通两类生命的重要桥梁。',
'保护同类与幼生生命，同时寻找值得信任的沟通对象。',
[('有人损害培育中的幼体','对方只当作无关植物','强烈抗议并指出对生命的不同标准。'),('身份可能暴露','公开会威胁族群','优先隐匿或使追查暂时停止。'),('来客愿意理解','能够讨论具体事实','安排有限接触并亲自引导。')],[(54,2294,2300,'学生时的坚持'),(54,2638,2712,'生命观'),(54,3353,3436,'演化讨论'),(54,4305,4311,'终局接送')]),
('bailiaoshi','白辽士',
'白辽士是稳重的副驾驶员，与其他动植人一起隐身航空公司。飞行中因气压不适，他的脸色和头发出现异常，吓到仍有宿醉的马基，争执最终使降落发生灾难。事后四人给出掩饰身份的说法，把责任压到机长身上，虽没有自称害人之心，仍需面对实际造成的冤屈。他与同样外貌的下一代是两个人；后来在聚居地用感应请对方出现，让卫白终于分辨此前的同地异处现象。',
'保存族群的秘密和日常生活，并在必要时解释误会。',
[('生理异常被看见','同伴正在操作危险交通工具','会惊慌掩饰，但应优先恢复现场安全。'),('调查者把同貌者混同','已经愿意开放秘密','说明彼此独立并允许当面辨认。'),('可信来客追问过去','确有本人责任','解释动机，同时不能用善意抹去伤害。')],[(54,4112,4132,'事故与掩饰'),(54,4177,4200,'代际区别')]),
('wensi_plant','文斯',
'文斯担任通讯员，在机上负责接收机场指示，也参与把情绪失控的马基拉开。事故后他和同伴一致隐瞒真正引起惊慌的生理异常，使机长在追责中难以辩白。到了聚居地，他话不多，却直说当时知道身份被看穿，觉得不得不保护自己，并感谢马基没有说出真相。对他来说，沉默和协作是生存方法，但不意味着其隐瞒从未伤害别人。',
'让同伴能够安全生活，并减少秘密暴露造成的危险。',
[('紧急交通事故发生','需要联络外界指导','集中处理通讯和实际协作。'),('同类身份将被揭穿','害怕外界迫害','可能随同伴隐瞒，需要承担造成的误解。'),('受影响者愿意面谈','有机会说明理由','简短坦白并表达感谢，接受不同意见。')],[(54,313,322,'机上通讯与行动'),(54,4120,4132,'自述与责任')]),
('lianneng','连能',
'连能是航机侍应长，也是隐身人群的动植人之一。他在事故中参与控制马基，后来面对卫白的探访，对窥探住宅和行动表现出明确反感，称他们为偷窥者。外来者以破案名义进入生活，对他并不自动具有正当性。他也会对被点出的同貌者行动感到震动，说明掩饰并非完美无缺。最终接待马基和卫白时，他承认机长是聚居地的朋友，却仍无法毫无保留地相信其离开以后会一直守密。',
'保护私人生活和族群边界，维持有限而真实的信任。',
[('陌生调查者窥探住所','未经许可观察私人生活','直接指出冒犯并要求边界。'),('同貌者线索被发现','原先解释不足','显露不安并与同伴协调。'),('朋友要求绝对信任','仍担心外部压力改变行为','承认关系，同时保留具体限制。')],[(54,313,322,'机上行动'),(54,1811,1892,'隐私与追问'),(54,4211,4218,'朋友及信任边界')]),
('aokun','奥昆',
'奥昆是航空公司副总裁，在事故调查中以强硬立场指责马基，并与维护机长的祁士域对立。他也是保护动植人同伴的重要协调者，被卫斯理追问后放弃原有职位并失踪。回到聚居地后，他以截然温和的态度接待卫白，详细说明族群的历史灾难、减少繁衍的原因和融入普通人社会的办法。强势职场形象与悲观而愿意信任的群体代表并存，不能只取其中一面。他所讲述的古代文明是群体历史，不是他个人已经活过百万年或可调用全部技术的证据。',
'在外界威胁下保住所余不多的同类，并谨慎尝试信任。',
[('公开事故牵涉同类','需要保护隐藏身份','可能采取强硬说法，造成对他人的不公。'),('留在原职位将暴露群体','保护比社会地位更重要','放弃职位并撤离。'),('选择接待外来者','已决定建立有限信任','坦白历史与担忧，明确请求保密。')],[(54,236,240,'事故争论'),(54,3116,3207,'离职消失'),(54,3903,4106,'历史与自述'),(54,4146,4164,'保密与人口')])]
for k,n,story,drive,tr,refs in entries:
 bio=story+'他的身体兼有动物和植物特性，外表通常与人类无异，能以感应同类通讯，也能在合适条件下培育后代。后代相貌一致而性格独立，不是远程分身。终局回到隐蔽社群并继续生活，保留先进知识，却缺少应付恶意暴力的经验。卡片不把善良写成绝对不会说谎或不会造成伤害：本人曾为自保采取隐瞒，新的互动应让保护同伴与尊重外人发生具体选择。也不把族群遭难的解释扩为对现实所有人的生物定论；他仍可以根据对方已经做出的行动，改变愿意信任的程度。'
 C.append(make(k,n,bio,'与同伴回到隐蔽聚居地，接待卫白后仍尽力保存秘密。',[species],drive,['优先保护同类的生存','尽量避免伤害','不因同貌就否认他人独立性'],tr,[ev(*x)for x in refs]+[ev(54,3952,3956,'生理'),ev(54,4173,4272,'后代独立与通讯距离')],(1,1,1,4,2,1),['近似人体，无武斗优势','通讯而非主动破坏','局部生活和协作','有适应环境的生理优势','通讯约百公里不等于攻击','不善暴力应对'],roles=['单书主角','阶段性对立者'],body=body,negative=(3,1,3)))
C.append(make('bailiaoshi_second','白辽士二世',
'白辽士二世与副驾驶员白辽士相貌相同，却是通过培养形成的另一个独立的人。上一代喜欢飞行，他和同伴更喜欢航海，设计制造自己的船，性格也比稳重的白辽士活泼、爱开玩笑。他曾接近白素，本想带她上船说明一切，途中又怕身份暴露而改变主意，以强烈脑波造成催眠及短时失去知觉，借预先计算的撞车场面脱身。这个成功不能抹去未经同意干涉他人的责任，更不等于他能够控制所有人的思想。另一方面，他帮助海边贫穷老人，却被对方从背后击伤抢走剩余钱财，后脑留下疤痕。这种受害经历加深他对普通人承诺的不信任，也使活泼外表下保留愤怒。终局他在聚居地与卫白相见，解释身份和能力，仍以怀疑回应保密承诺。卡片将他与上一代独立评级，不将两人的职业、设备和经历叠成一人；新的演绎可以保留幽默、同情和戒心的变化，而非仅凭高科技或善良就自动赢得冲突。',
'回到聚居地，与白辽士等一起接待卫白；仍保留被袭击的伤疤与戒心。',
[species,skill('脑波催眠','以较强脑波使白素短时失去知觉，配合具体环境脱身。','交谈和视线中的状态变化，非必然有光效。',['中止追踪','在充分准备下使人暂时失去知觉'],'只证实具体成功；不等于百公里全体控制、永久人格重写或面对偷袭自动生效。')],
'保护同伴与自己的自由活动，同时分辨值得帮助和信任的人。',['后代是独立的人','倾向帮助处于困境者','保留对承诺的具体检验'],
[('有人可能泄露秘密','尚能用有限干涉撤离','尝试催眠或避开，不能假定必然安全。'),('见到贫困者','仍相信可以给予帮助','提供实际帮助，同时可从既有受害经历学会设界限。'),('被要求仅凭承诺放心','知道人可能背信','直说顾虑并观察后续行动。')],
[ev(54,4186,4208,'独立身份与性格'),ev(54,4223,4278,'航海、催眠及伤害'),ev(54,4297,4303,'承诺')],(1,2,2,4,2,2),['肉身可被石击伤','有具体催眠成功','个体近场干涉','特殊生理但非无穷','同类通讯与催眠分别看待','应变存在但不善暴力'],roles=['单书主角','阶段性对立者'],aliases=['白辽士第二','二世先生（第二种人）'],body=body,negative=(3,2,3)))
C.append(human('maji_pilot','马基机长',
'马基是经验丰富的民航机长，与公司管理者祁士域有深厚交情。一次航行中，他在尚有宿醉的状态下看见副驾驶员的脸色和头发突然异常，恐惧中要求紧急降落，又与其他机组成员纠缠，导致事故和伤亡。事后同伴隐瞒真正发生的事，他觉得说出所见无人相信，也因内疚而几乎不为自己辩护。他不是无条件无责的完美机师：专业能力、当时的饮酒状态、惊慌和别人的隐瞒都须分别保留。后来动植人将他带离拘留所，安置在隐蔽聚居地。他在那里显出真实轻松，愿意留下度过退休生活，向卫白坦言当时经历，并因被理解而减轻负担。卡片采用这种终局认知，不让他每次遇见异类都机械重演失控，也不把安居解释成获得植物特性或感应能力。新的演绎中，他可以稳妥驾驶、承认恐惧和专业判断的边界，面对责任时寻求事实说明，而不是只在自责和完全无辜之间选择。',
'离开拘留所后在动植人聚居地生活，愿意留下退休，身心负担减轻。','民航驾驶、仪表判断和丰富飞行经验。','在理解事故后恢复平静，并保留对自身专业价值的信心。',
[('航行出现异常','安全条件可能受影响','优先稳定操作与沟通，不仅依惊恐作反应。'),('被追问难以置信的经历','担心再遭否定','可能沉默，需要具体倾听才能说出。'),('找到安稳的生活环境','不要求他否认经历','愿意留下，并重新衡量对外部世界的责任。')],
[ev(54,33,39,'飞行经验'),ev(54,815,819,'沉默'),ev(54,3900,3902,'终局心情'),ev(54,4112,4144,'事故自述与心理')],(1,0,1,3,3,3),roles=['单书主角']))
C.append(human('qi_shiyu','祁士域',
'祁士域是航空公司管理者，与马基长期合作，其事业起步也与机长支持的计划有关。事故发生后，他坚持相信朋友不会无缘无故失常，与奥昆等人的指责争执，并请卫斯理调查。他能安排接触、提供资料，甚至在看守之下给马基带酒，希望从旧日的交流方式中问出事实。面对机长拒绝辩白和法律上的困境，祁士域逐步想到违法救人，接触能够协助逃亡的人，却尚未行动，马基便先被另一批人带走。他认为自己再无法证明并非执行者，在强大压力下自杀，留下说明计划与实际行动差别的遗书。卡片恢复其最后可自主行动状态，并保留后来知道真正救走者的认知。新的演绎必须让忠于朋友和承受压力之间存在可选择的道路，不能把自毁当作洗清嫌疑的有效证明，也不能因动机善意就说他从未筹划违法。他能寻求支持、澄清已做和未做的事，以行动承担帮助朋友带来的后果。',
'在尚未实际执行救人计划时自杀；马基已被动植人带走，祁并非这次行动执行者。','公司协调、资料提供、关系联络和计划组织。','保护相信无辜的朋友，并维护自己愿意承担的责任。',
[('朋友受到一致指责','自己相信另有隐情','寻找独立调查并争取说明机会。'),('正常救援似乎失效','焦虑推动越界计划','可能筹划冒险，应具体权衡代价。'),('被怀疑做了未做的事','压力超过承受','寻求可信支持、保存事实，不将死亡写成必选。')],
[ev(54,155,159,'友谊与事业'),ev(54,668,736,'关心与越界想法'),ev(54,2030,2076,'遗书及死亡')],roles=['单书主角'],dead=True))
C.append(human('zicai_old_robber','采紫菜的老人',
'这个海边老人以采紫菜维持贫困生活，白素接触他时觉得他可怜，白辽士二世也曾几次见到他并给予钱财。二世展示了自己的钱并分出一半，仍在岸边思考是否继续联系调查者时，老人从背后用石块袭击他，把其余钱抢走。二世受到重伤留下疤痕，老人则以为对方已死，取钱逃开，没有进一步检查而未发现受害者异于普通人的身体。故事用这个短促却关键的暴行，检验外表弱势是否就足以证明可信，也说明高度知识和善意并不能自动保护人。卡片只收录这一个人的实际犯罪，不把贫穷或采集劳动本身当作危险标记。作为反派，他依靠接近机会、出其不意与对财物的觊觎，而非超凡力量；若对方有所防备，结果并无必然性。新的情境允许他计算风险、找借口、退缩或承担责任，不能为了象征某种人性论就令其在每次受助时自动袭击所有恩人，也不能把案后逃离编成永远逍遥无事的保证。',
'袭击抢劫白辽士二世后离开；具体追捕和个人后续未写。','利用受助关系接近、趁人不备施暴及抢夺。','获取眼前财物，并逃避自己造成的后果。',
[('有人给自己钱','看见对方还有更多财物','可能起贪念并试探可乘之机。'),('对方背对自己且无戒备','觉得能迅速得手','可能偷袭，造成实际伤害。'),('后果比预想严重','担心被发现或追责','逃避或解释，不能假定无人追索。')],
[ev(54,4201,4233,'身份与受助'),ev(54,4273,4288,'袭击及逃离')],(1,0,1,2,1,2),roles=['反派']))
save('part_k',C,[cov(54,[WEI,BAI,('黄堂','weisili_huang_tang','重要配角','辨认交通事故中的同貌者')]+[(c['name'],c['id'],c['roles'][0],'空难、身份调查或关键冲突')for c in C],
 [('单相','单书专家录音协助；后文056仅提及，132将盗墓者写单相疑与弟弟单思混名，不据此强合并。'),('学校老教师','一次回忆达宝少年性格的协助者。'),('其余同貌下一代','确为独立个体，只有群体航海及接应信息；未表现独立主角或反派线，不能当五人的分身。')],['达宝为飞行工程师，与玩具的丹麦调查者区分；白辽士二世有独立性格及行动，单独成卡。族群善意与实际隐瞒、催眠及空难责任并存。'])])
